57:     bool mbm_file::do_read_headers() {
58:         if (stream->read(&header, sizeof(uint32_t)) != sizeof(uint32_t)) {
59:             return false;
60:         }
61:         if (header.uids.uid1 == 0x10000041) {
62:             is_rom_version = true;
63:             header.trailer_off = 4;
64:         } else {
65:             is_rom_version = false;
66: 
67:             stream->seek(0, common::seek_where::beg);
68:             if (stream->read(&header, sizeof(header)) != sizeof(header)) {
69:                 return false;
70:             }
71:         }
72: 
73:         stream->seek(header.trailer_off, common::seek_where::beg);
74: 
75:         // Go to trailer, let's grab all those single bitmap header offsets
76:         if (stream->read(&trailer.count, sizeof(trailer.count)) != sizeof(trailer.count)) {
77:             return false;
78:         }
79: 
80:         if (trailer.count > 0xFFFF) {
81:             return false;
82:         }
83: 
84:         trailer.sbm_offsets.resize(trailer.count);
85:         std::fill(trailer.sbm_offsets.begin(), trailer.sbm_offsets.end(), 0);
86: 
87:         sbm_headers.resize(trailer.count);
88: 
89:         auto do_load_header = [this](const std::size_t index) {
90:             stream->seek(header.trailer_off + (index + 1) * 4, common::seek_where::beg);
91: 
92:             if (stream->read(&trailer.sbm_offsets[index], 4) != 4) {
93:                 return false;
94:             }
95: 
96:             // Remember the current offset first
97:             if (is_rom_version) {
98:                 stream->seek(trailer.sbm_offsets[index] + 5 * sizeof(std::uint32_t), common::seek_where::beg);
99:             } else {
100:                 stream->seek(trailer.sbm_offsets[index], common::seek_where::beg);
101:             }
102: 
103:             if (!sbm_headers[index].internalize(*stream)) {
104:                 return false;
105:             }
106: 
107:             // ROM bitmaps are stored as in-memory CBitwiseBitmaps, whose RLE types are offset by 50.
108:             if (is_rom_version && (sbm_headers[index].compression >= ROM_BITMAP_COMPRESSION_BASE)) {
109:                 sbm_headers[index].compression -= ROM_BITMAP_COMPRESSION_BASE;
110:             }
111: 
112:             return true;
113:         };
114: 
115:         if (index_to_loads.empty()) {
116:             for (std::size_t i = 0; i < trailer.sbm_offsets.size(); i++) {
117:                 if (!do_load_header(i))
118:                     return false;
119:             }
120:         } else {
121:             for (const std::size_t i : index_to_loads) {
122:                 // A client may ask for a bitmap index this MBM does not have — the
123:                 // FBS client passes whatever the guest requested. Skip it instead of
124:                 // indexing the trailer out of bounds; the caller checks the result
125:                 // with is_header_loaded() and reports not-found. The out-of-bounds
126:                 // read is silent undefined behaviour with an unhardened libc++ and
127:                 // an abort with a hardened one.
128:                 if (i >= trailer.sbm_offsets.size()) {
129:                     continue;
130:                 }
131: 
132:                 if (!do_load_header(i))
133:                     return false;
134: 
135:                 if (is_rom_version && ((i + 1) < trailer.sbm_offsets.size())) {
136:                     if (!do_load_header(i + 1)) {
137:                         return false;
138:                     }
139:                 }
140:             }
141: 
142:             index_to_loads.clear();
143:         }
144: 
145:         return valid();
146:     }
